-- Neighboar relational schema (3NF, nine tables).
-- Applied by db/migrate.py as neighboar_owner, inside one transaction.
-- Column meanings and source fields: docs/data_dictionary.md.
--
-- Identity columns are GENERATED BY DEFAULT so the ETL can COPY its
-- deterministic ids; etl/load_pg.py resets every sequence afterwards.

-- ------------------------------------------------------------------ lookups

CREATE TABLE town (
    town_id  SMALLINT    PRIMARY KEY,
    code     VARCHAR(3)  NOT NULL UNIQUE,
    name     VARCHAR(40) NOT NULL UNIQUE
);
COMMENT ON TABLE town IS 'HDB town: property-dataset code and resale-dataset name (27 rows).';

CREATE TABLE flat_type (
    flat_type_id    SMALLINT    PRIMARY KEY,
    name            VARCHAR(20) NOT NULL UNIQUE,
    is_resale_type  BOOLEAN     NOT NULL
);
COMMENT ON TABLE flat_type IS 'Flat types: 7 resale types plus STUDIO APARTMENT and OTHER, which appear only in supply counts.';

CREATE TABLE flat_model (
    flat_model_id  SMALLINT    PRIMARY KEY,
    name           VARCHAR(30) NOT NULL UNIQUE
);
COMMENT ON TABLE flat_model IS 'Flat models as spelled in the resale dataset (21 rows).';

-- ------------------------------------------------------------------ buildings

CREATE TABLE building (
    building_id          INT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    town_id              SMALLINT     NOT NULL REFERENCES town,
    block                VARCHAR(5)   NOT NULL,
    street               VARCHAR(40)  NOT NULL,
    year_completed       SMALLINT     CHECK (year_completed BETWEEN 1900 AND 2100),
    lease_commence_year  SMALLINT     CHECK (lease_commence_year BETWEEN 1900 AND 2100),
    max_floor            SMALLINT     CHECK (max_floor BETWEEN 1 AND 60),
    residential          BOOLEAN,
    commercial           BOOLEAN,
    market_hawker        BOOLEAN,
    miscellaneous        BOOLEAN,
    multistorey_carpark  BOOLEAN,
    precinct_pavilion    BOOLEAN,
    in_property_dataset  BOOLEAN      NOT NULL,
    latitude             NUMERIC(9,6) CHECK (latitude BETWEEN 1.15 AND 1.48),
    longitude            NUMERIC(9,6) CHECK (longitude BETWEEN 103.59 AND 104.10),
    CONSTRAINT building_block_street_key UNIQUE (block, street),
    CONSTRAINT building_coords_both_or_neither CHECK ((latitude IS NULL) = (longitude IS NULL)),
    -- A block from the property dataset has all its attributes; a stub (sales but
    -- no property row) has none, so nothing is invented for it.
    CONSTRAINT building_property_attrs CHECK (
        CASE WHEN in_property_dataset THEN
            year_completed IS NOT NULL AND max_floor IS NOT NULL
            AND residential IS NOT NULL AND commercial IS NOT NULL AND market_hawker IS NOT NULL
            AND miscellaneous IS NOT NULL AND multistorey_carpark IS NOT NULL AND precinct_pavilion IS NOT NULL
        ELSE
            year_completed IS NULL AND max_floor IS NULL
            AND residential IS NULL AND commercial IS NULL AND market_hawker IS NULL
            AND miscellaneous IS NULL AND multistorey_carpark IS NULL AND precinct_pavilion IS NULL
        END
    )
);
COMMENT ON TABLE building IS 'HDB block. lease_commence_year is a block attribute (3NF); stubs have in_property_dataset = false.';

CREATE TABLE building_flat_supply (
    building_id   INT      NOT NULL REFERENCES building ON DELETE CASCADE,
    flat_type_id  SMALLINT NOT NULL REFERENCES flat_type,
    sold_units    INT      NOT NULL CHECK (sold_units >= 0),
    rental_units  INT      NOT NULL CHECK (rental_units >= 0),
    PRIMARY KEY (building_id, flat_type_id),
    CONSTRAINT supply_not_empty CHECK (sold_units + rental_units > 0)
);
COMMENT ON TABLE building_flat_supply IS 'Units per block and flat type. Pairs with no units are not stored.';

-- ------------------------------------------------------------------ sales

CREATE TABLE resale_transaction (
    txn_id                  BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    building_id             INT          NOT NULL REFERENCES building,
    flat_type_id            SMALLINT     NOT NULL REFERENCES flat_type,
    flat_model_id           SMALLINT     NOT NULL REFERENCES flat_model,
    txn_month               DATE         NOT NULL CHECK (EXTRACT(DAY FROM txn_month) = 1),
    storey_min              SMALLINT     NOT NULL,
    storey_max              SMALLINT     NOT NULL,
    floor_area_sqm          NUMERIC(5,1) NOT NULL CHECK (floor_area_sqm > 0 AND floor_area_sqm < 400),
    remaining_lease_months  SMALLINT     NOT NULL CHECK (remaining_lease_months BETWEEN 0 AND 1188),
    resale_price            NUMERIC(9,2) NOT NULL CHECK (resale_price > 0),
    source                  VARCHAR(8)   NOT NULL CHECK (source IN ('snapshot', 'admin')),
    CONSTRAINT storey_band CHECK (1 <= storey_min AND storey_min <= storey_max AND storey_max <= 60)
);
COMMENT ON TABLE resale_transaction IS 'One row per resale. Identical rows are distinct sales (no unit number in the source).';
COMMENT ON COLUMN resale_transaction.source IS 'Provenance: snapshot (loaded by the ETL) or admin (recorded through the app). No default, so every insert must say which. Admin rows can be removed before a benchmark; snapshot rows an admin deleted come back only with a reload.';

-- ------------------------------------------------------------------ accounts

CREATE TABLE buyer (
    buyer_id        INT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email           VARCHAR(254) NOT NULL CHECK (position('@' IN email) > 1),
    password_hash   TEXT         NOT NULL,
    display_name    VARCHAR(60),
    is_admin        BOOLEAN      NOT NULL DEFAULT false,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_active_at  TIMESTAMPTZ
);
CREATE UNIQUE INDEX buyer_email_lower_key ON buyer (lower(email));
COMMENT ON TABLE buyer IS 'App account. Email is unique ignoring case; password_hash is argon2id.';

CREATE TABLE saved_building (
    buyer_id     INT          NOT NULL REFERENCES buyer ON DELETE CASCADE,
    building_id  INT          NOT NULL REFERENCES building ON DELETE RESTRICT,
    note         VARCHAR(500),
    saved_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (buyer_id, building_id)
);
COMMENT ON TABLE saved_building IS 'M:N between buyer and building. At most 50 per buyer (trigger).';

-- ------------------------------------------------------------------ food access

CREATE TABLE hawker_centre (
    hawker_id    INT          PRIMARY KEY,
    name         VARCHAR(100) NOT NULL,
    address      VARCHAR(100),
    postal_code  CHAR(6)      CHECK (postal_code ~ '^[0-9]{6}$'),
    status       VARCHAR(30)  NOT NULL,
    stall_count  SMALLINT     CHECK (stall_count >= 0),
    latitude     NUMERIC(9,6) NOT NULL CHECK (latitude BETWEEN 1.15 AND 1.48),
    longitude    NUMERIC(9,6) NOT NULL CHECK (longitude BETWEEN 103.59 AND 104.10)
);
COMMENT ON TABLE hawker_centre IS 'NEA hawker centres. No FK to building: proximity is computed (Haversine), not stored.';
